"use client"

import { useState } from "react"
import Link from "next/link"
import { Sidebar } from "@/components/sidebar"
import { TopBar } from "@/components/topbar"
import { Button } from "@/components/ui/button"
import { Card } from "@/components/ui/card"
import { Input } from "@/components/ui/input"

interface HistoryItem {
  id: string
  title: string
  url: string
  addedDate: string
  processedDate?: string
  duration: string
  status: "completed" | "processing" | "failed"
}

export default function HistoryPage() {
  const [searchTerm, setSearchTerm] = useState("")
  const [filterStatus, setFilterStatus] = useState<"all" | "completed" | "processing" | "failed">("all")

  const historyItems: HistoryItem[] = [
    {
      id: "1",
      title: "Introduction to Machine Learning",
      url: "https://youtube.com/watch?v=example1",
      addedDate: "2024-12-01",
      processedDate: "2024-12-01",
      duration: "45 min",
      status: "completed",
    },
    {
      id: "2",
      title: "Advanced Python Concepts",
      url: "https://youtube.com/watch?v=example2",
      addedDate: "2024-11-28",
      processedDate: "2024-11-28",
      duration: "52 min",
      status: "completed",
    },
    {
      id: "3",
      title: "Web Development Fundamentals",
      url: "https://youtube.com/watch?v=example3",
      addedDate: "2024-11-25",
      duration: "38 min",
      status: "processing",
    },
    {
      id: "4",
      title: "Data Science Basics",
      url: "https://youtube.com/watch?v=example4",
      addedDate: "2024-11-20",
      duration: "60 min",
      status: "failed",
    },
    {
      id: "5",
      title: "Cloud Computing with AWS",
      url: "https://youtube.com/watch?v=example5",
      addedDate: "2024-11-15",
      processedDate: "2024-11-15",
      duration: "48 min",
      status: "completed",
    },
  ]

  const filteredItems = historyItems.filter((item) => {
    const matchesSearch = item.title.toLowerCase().includes(searchTerm.toLowerCase())
    const matchesStatus = filterStatus === "all" || item.status === filterStatus
    return matchesSearch && matchesStatus
  })

  const getStatusColor = (status: string) => {
    switch (status) {
      case "completed":
        return "bg-green-500/10 text-green-700"
      case "processing":
        return "bg-yellow-500/10 text-yellow-700"
      case "failed":
        return "bg-red-500/10 text-red-700"
      default:
        return "bg-gray-500/10 text-gray-700"
    }
  }

  const getStatusIcon = (status: string) => {
    switch (status) {
      case "completed":
        return "✓"
      case "processing":
        return "⏳"
      case "failed":
        return "✕"
      default:
        return "•"
    }
  }

  return (
    <div className="flex h-screen bg-background">
      <Sidebar />

      <div className="flex-1 flex flex-col overflow-hidden">
        <TopBar />

        <main className="flex-1 overflow-auto">
          <div className="p-8 max-w-6xl mx-auto space-y-8">
            {/* Header */}
            <div className="space-y-2">
              <h1 className="text-3xl font-bold text-foreground">Video History</h1>
              <p className="text-muted-foreground">View and manage all your processed lecture videos</p>
            </div>

            {/* Search and Filter */}
            <Card className="p-6 border-border/50 space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="md:col-span-2">
                  <Input
                    placeholder="Search by video title..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                  />
                </div>
                <div className="flex gap-2">
                  {(["all", "completed", "processing", "failed"] as const).map((status) => (
                    <Button
                      key={status}
                      size="sm"
                      variant={filterStatus === status ? "default" : "outline"}
                      onClick={() => setFilterStatus(status)}
                      className={filterStatus === status ? "bg-primary hover:bg-primary/90" : ""}
                    >
                      {status.charAt(0).toUpperCase() + status.slice(1)}
                    </Button>
                  ))}
                </div>
              </div>
            </Card>

            {/* History List */}
            <div className="space-y-3">
              {filteredItems.length > 0 ? (
                filteredItems.map((item) => (
                  <Card key={item.id} className="p-4 border-border/50 hover:border-border transition-colors">
                    <div className="flex items-center justify-between gap-4">
                      <div className="flex-1 min-w-0">
                        <h3 className="font-semibold text-foreground truncate">{item.title}</h3>
                        <div className="flex gap-4 mt-2 text-sm text-muted-foreground">
                          <span>Added: {item.addedDate}</span>
                          {item.processedDate && <span>Processed: {item.processedDate}</span>}
                          <span>Duration: {item.duration}</span>
                        </div>
                      </div>

                      <div className="flex items-center gap-3">
                        <div
                          className={`px-3 py-1 rounded-full text-xs font-medium flex items-center gap-1 ${getStatusColor(
                            item.status,
                          )}`}
                        >
                          <span>{getStatusIcon(item.status)}</span>
                          {item.status.charAt(0).toUpperCase() + item.status.slice(1)}
                        </div>

                        {item.status === "completed" && (
                          <div className="flex gap-2">
                            <Link href={`/summary/${item.id}`}>
                              <Button size="sm" variant="outline">
                                Summary
                              </Button>
                            </Link>
                            <Link href={`/concept-map/${item.id}`}>
                              <Button size="sm" className="bg-accent hover:bg-accent/90">
                                Map
                              </Button>
                            </Link>
                          </div>
                        )}

                        {item.status === "failed" && (
                          <Button size="sm" variant="outline">
                            Retry
                          </Button>
                        )}
                      </div>
                    </div>
                  </Card>
                ))
              ) : (
                <Card className="p-8 border-border/50 text-center">
                  <p className="text-muted-foreground">No videos found matching your criteria</p>
                </Card>
              )}
            </div>

            {/* Stats */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <Card className="p-6 border-border/50 text-center">
                <p className="text-3xl font-bold text-primary mb-2">
                  {historyItems.filter((i) => i.status === "completed").length}
                </p>
                <p className="text-sm text-muted-foreground">Completed Videos</p>
              </Card>
              <Card className="p-6 border-border/50 text-center">
                <p className="text-3xl font-bold text-accent mb-2">
                  {historyItems.filter((i) => i.status === "processing").length}
                </p>
                <p className="text-sm text-muted-foreground">Processing</p>
              </Card>
              <Card className="p-6 border-border/50 text-center">
                <p className="text-3xl font-bold text-destructive mb-2">
                  {historyItems.filter((i) => i.status === "failed").length}
                </p>
                <p className="text-sm text-muted-foreground">Failed</p>
              </Card>
            </div>
          </div>
        </main>
      </div>
    </div>
  )
}
